<?php
declare(strict_types=1);
require_once __DIR__ . '/../../app/services.php';
$db=db();$step=$_GET['step']??'identity';
$themeOptions=['minimal'=>['Minimal','Quiet structure, generous whitespace, product-led.'],'neomorphism'=>['Neomorphism','Soft dimensional surfaces and gentle shadows.'],'skeuomorphism'=>['Skeuomorphism','Tactile, physical UI details and material depth.'],'glassmorphism'=>['Glassmorphism','Translucent layered surfaces and blur.'],'claymorphism'=>['Claymorphism','Rounded, friendly, tactile components.'],'maximalism'=>['Maximalism','Expressive color, layered visual energy.'],'brutalism'=>['Brutalism','Hard borders, high contrast and bold structure.']];
if($_SERVER['REQUEST_METHOD']==='POST')try{verify_csrf();$action=$_POST['action']??'';
 if($action==='identity'){$name=trim($_POST['name']??'');$email=filter_var($_POST['email']??'',FILTER_VALIDATE_EMAIL);$password=$_POST['password']??'';if(!$name||!$email||strlen($password)<8)throw new RuntimeException('Add a store name, valid email, and password of at least 8 characters.');$slug=slug($name);$check=$db->prepare('SELECT id FROM tenants WHERE slug=?');$check->execute([$slug]);if($check->fetch())$slug.='-'.bin2hex(random_bytes(2));$db->beginTransaction();$s=$db->prepare('INSERT INTO tenants (slug,name,tagline,description) VALUES (?,?,?,?)');$s->execute([$slug,$name,trim($_POST['tagline']??''),trim($_POST['description']??'')]);$tenantId=(int)$db->lastInsertId();$u=$db->prepare('INSERT INTO users (tenant_id,role,name,email,password_hash) VALUES (?,?,?,?,?)');$u->execute([$tenantId,'admin',trim($_POST['owner_name']??'Store owner'),$email,password_hash($password,PASSWORD_DEFAULT)]);$db->commit();$_SESSION['user_id']=$db->lastInsertId();flash('Brand identity saved. Choose your storefront theme.');redirect('/setup?store='.$slug.'&step=theme');}
 if($action==='theme'){$tenant=current_tenant($db);require_admin($db,$tenant);$theme=array_key_exists($_POST['theme']??'',$themeOptions)?$_POST['theme']:'minimal';$colors=['primary_color'=>preg_match('/^#[a-fA-F0-9]{6}$/',$_POST['primary_color']??'')?$_POST['primary_color']:'#6D5EF2','secondary_color'=>preg_match('/^#[a-fA-F0-9]{6}$/',$_POST['secondary_color']??'')?$_POST['secondary_color']:'#E9E6FF','accent_color'=>preg_match('/^#[a-fA-F0-9]{6}$/',$_POST['accent_color']??'')?$_POST['accent_color']:'#F37B5B'];$db->prepare('UPDATE tenants SET theme=?,primary_color=?,secondary_color=?,accent_color=?,show_brand_name=? WHERE id=?')->execute([$theme,$colors['primary_color'],$colors['secondary_color'],$colors['accent_color'],isset($_POST['show_brand_name'])?1:0,$tenant['id']]);flash('Theme applied. Your admin workspace is ready.');redirect('/admin/?store='.$tenant['slug']);}
}catch(Throwable $e){if($db->inTransaction())$db->rollBack();flash($e->getMessage(),'error');redirect('/setup'.($step==='theme'?'?step=theme':''));}
$tenant=null;if($step==='theme'){try{$tenant=current_tenant($db);require_admin($db,$tenant);}catch(Throwable $e){redirect('/setup');}}
?><!doctype html><html lang="en"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>Setup · E-Com Minutes</title><link rel="stylesheet" href="/assets/tailwind.css"><link href="https://fonts.googleapis.com/css2?family=DM+Sans:wght@400;500;600;700&family=Playfair+Display:ital,wght@0,600;1,600&display=swap" rel="stylesheet"><style>body{font-family:DM Sans,sans-serif}.display{font-family:Playfair Display,serif}.theme-card:has(input:checked){border-color:#171717;box-shadow:4px 4px #171717}.theme-preview{height:5rem;position:relative;overflow:hidden}.theme-preview:before,.theme-preview:after{content:"";position:absolute}.theme-preview.minimal{background:#f4f2ec}.theme-preview.minimal:before{inset:14px;background:#6D5EF2}.theme-preview.neomorphism{background:#eceae6;box-shadow:inset 8px 8px 14px #d2d0cb,inset -8px -8px 14px #fff}.theme-preview.skeuomorphism{background:linear-gradient(145deg,#b28b65,#6b4b35)}.theme-preview.glassmorphism{background:linear-gradient(135deg,#b7b0e7,#f3c9d2)}.theme-preview.glassmorphism:before{inset:12px;border:1px solid #fff;background:rgba(255,255,255,.35);backdrop-filter:blur(4px)}.theme-preview.claymorphism{background:#efd7c9;border-radius:20px}.theme-preview.claymorphism:before{inset:14px;border-radius:14px;background:#f8a580;box-shadow:inset 0 3px #ffd9c7}.theme-preview.maximalism{background:radial-gradient(circle at 20% 30%,#ffcb74 0 20%,transparent 21%),radial-gradient(circle at 75% 60%,#8e7ee6 0 26%,transparent 27%),#f7d8eb}.theme-preview.brutalism{background:#f7e545;border:3px solid #171717}.theme-preview.brutalism:before{left:10px;bottom:10px;width:45%;height:55%;background:#ed7054;border:2px solid #171717}</style></head><body class="min-h-screen bg-stone-100 p-5"><?=show_flash()?><main class="mx-auto my-8 w-full max-w-4xl rounded-2xl bg-white p-7 shadow-sm"><div class="flex items-center justify-between"><a class="font-bold" href="/">E-Com <em class="display">Minutes</em></a><span class="text-xs font-bold tracking-[.2em] text-stone-500">SETUP <?= $step==='theme'?'02 / 02':'01 / 02'?></span></div><?php if($step!=='theme'):?><div class="mt-8 max-w-xl"><h1 class="display text-5xl">Start with<br><em class="text-violet-600">your brand.</em></h1><p class="mt-4 text-sm leading-6 text-stone-600">Create an isolated tenant and administrator. The next layer gives you every requested storefront theme before entering admin.</p><form method="post" class="mt-7 space-y-4"><?=csrf_input()?><input type="hidden" name="action" value="identity"><div class="grid gap-4 sm:grid-cols-2"><label class="text-sm">Store name<input required name="name" class="mt-1 w-full border border-stone-300 p-3"></label><label class="text-sm">Your name<input name="owner_name" class="mt-1 w-full border border-stone-300 p-3"></label></div><label class="text-sm">Tagline<input name="tagline" class="mt-1 w-full border border-stone-300 p-3"></label><label class="text-sm">Brand story<textarea name="description" class="mt-1 w-full border border-stone-300 p-3"></textarea></label><div class="grid gap-4 sm:grid-cols-2"><label class="text-sm">Admin email<input required type="email" name="email" class="mt-1 w-full border border-stone-300 p-3"></label><label class="text-sm">Password<input required minlength="8" type="password" name="password" class="mt-1 w-full border border-stone-300 p-3"></label></div><button class="w-full rounded bg-zinc-900 p-3 text-sm font-bold text-white">Continue to themes →</button></form></div><?php else:?><div class="mt-8"><h1 class="display text-5xl">Choose the layer<br><em class="text-violet-600">your brand lives in.</em></h1><p class="mt-4 max-w-2xl text-sm leading-6 text-stone-600">Every theme is a real storefront treatment. You can switch it at any time in Admin → Storefront without touching catalog data.</p><form method="post" class="mt-7"><?=csrf_input()?><input type="hidden" name="action" value="theme"><div class="grid gap-4 sm:grid-cols-2 lg:grid-cols-3 xl:grid-cols-4"><?php foreach($themeOptions as $key=>[$name,$copy]):?><label class="theme-card cursor-pointer rounded-xl border-2 border-stone-200 p-3 transition"><input class="sr-only" type="radio" name="theme" value="<?=e($key)?>" <?=$key==='minimal'?'checked':''?>><div class="theme-preview <?=$key?>"></div><b class="mt-3 block text-sm"><?=e($name)?></b><small class="mt-1 block text-xs leading-5 text-stone-500"><?=e($copy)?></small></label><?php endforeach;?></div><div class="mt-7 grid gap-4 sm:grid-cols-3"><label class="text-xs font-bold">Primary<input name="primary_color" value="#6D5EF2" class="mt-1 w-full border p-3"></label><label class="text-xs font-bold">Soft surface<input name="secondary_color" value="#E9E6FF" class="mt-1 w-full border p-3"></label><label class="text-xs font-bold">Accent<input name="accent_color" value="#F37B5B" class="mt-1 w-full border p-3"></label></div><label class="mt-5 inline-flex text-sm"><input class="mr-2" type="checkbox" name="show_brand_name" checked>Show brand name beside uploaded logo</label><button class="mt-7 w-full rounded bg-zinc-900 p-3 text-sm font-bold text-white">Apply theme and open admin →</button></form></div><?php endif;?></main></body></html>
